/*
 * A285432  Positions of 0 in A286939; complement of A285564.
 * https://oeis.org/A285432
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 0 in A286939, the fixed point of
 *            00->001, 1->000, starting from 00; the word is generated by
 *            iterating the mapping
 * Range:     u8 n <= 203, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 82 terms through n = 8705 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static unsigned char *A285432_w = NULL;
static idx_t A285432_len = 0;
static idx_t A285432_zeros = 0;

static void A285432_grow(idx_t nzeros) {
    if (A285432_w == NULL) {
        A285432_w = (unsigned char *)malloc(4);
        A285432_w[0] = 0;
        A285432_w[1] = 0;
        A285432_len = 2;
        A285432_zeros = 2;
    }
    while (A285432_zeros < nzeros) {
        idx_t cap = A285432_len * 3 + 10;
        unsigned char *nb = (unsigned char *)malloc((size_t)cap);
        idx_t nl = 0, z = 0, i;
        for (i = 0; i < A285432_len; ++i) {
            if (A285432_w[i] == 0 && i + 1 < A285432_len && A285432_w[i + 1] == 0) {
                nb[nl++] = 0;
                nb[nl++] = 0;
                nb[nl++] = 1;
                z += 2;
                ++i;
            } else if (A285432_w[i] == 1) {
                nb[nl++] = 0;
                nb[nl++] = 0;
                nb[nl++] = 0;
                z += 3;
            } else {
                nb[nl++] = 0;
                z += 1;
            }
        }
        free(A285432_w);
        A285432_w = nb;
        A285432_len = nl;
        A285432_zeros = z;
    }
}

seq_t a(idx_t n) {
    idx_t i, cnt = 0;
    if (n == 0) return (seq_t)0;
    A285432_grow(n);
    for (i = 0; i < A285432_len; ++i) {
        if (A285432_w[i] == 0) {
            ++cnt;
            if (cnt == n) return (seq_t)(i + 1);
        }
    }
    return (seq_t)0;
}
